quests[75491] = { id = 75491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glub", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78157] = { id = 78157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[78752] = { id = 78752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweise: Titanenrune mit Protokoll Gamma", description = "Die Präsenz des Lichkönigs darf sich nicht weiter ausbreiten!\n\nDer Rat der Sechs hat erlassen, dass alle, die stark genug sind, zu den Waffen greifen und dabei helfen sollen, Azeroth zu bewahren!", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein Medaillon der Entweihten von einem beliebigen, finalen Dungeonboss bringt.\n\nDiese Quest kann nur in einem Titanenrunendungeon mit aktivem Protokoll Gamma abgeschlossen werden.", progress = "Wir sprechen uns erneut, {name}. Bedeutet das, dass Ihr in der Erfüllung Eurer Pflichten erfolgreich wart?", completion = "Welch Übel sich darin verbirgt!\n\nIch werde es für weitere Untersuchungen zurück zum Rat der Sechs bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78753] = { id = 78753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweise: Bedrohungen für Azeroth", description = "Wir müssen den Druck an allen Fronten weiter aufrechthalten!\n\nDer Rat der Sechs hat erlassen, dass alle gewillten Kämpfer zu den Waffen greifen und dabei helfen sollen, Azeroth zu bewahren!", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein geheimnisvolles Artefakt von einem beliebigen, finalen Dungeonboss bringt.\n\nDiese Quest kann nur in einem heroischen Dungeon abgeschlossen werden.", progress = "Wo liegt das Problem? Warum habt Ihr noch keine dieser Bedrohungen beseitigt?", completion = "Was für ein interessanter Fund!\n\nIch werde ihn für weitere Untersuchungen zurück zum Rat der Sechs bringen.", sourceObjectiveStatus = "unverified-source-field" }
